    //reduceSmem
	CHECK(cudaMemcpy(idata_dev, idata_host, bytes, cudaMemcpyHostToDevice));
	CHECK(cudaDeviceSynchronize());
	iStart = cpuSecond();
	reduceSmem <<<grid.x, block>>>(idata_dev, odata_dev, size);
